[
  {
    "question": "Which of the following most accurately defines a **schema** in a database system?",
    "options": {
      "A": "The actual data values stored in the database at a particular moment.",
      "B": "A collection of system tables that describe the structure of the database.",
      "C": "The logical description of the database’s tables, attributes, and constraints.",
      "D": "A set of SQL queries used to retrieve data from the database."
    },
    "correct_answer": "C",
    "explanation": "A schema is the stable logical description of the database – it specifies tables, attributes, data types, and constraints, but not the current data values.",
    "difficulty": "Medium"
  },
  {
    "question": "How does an **instance** differ from a **schema**?",
    "options": {
      "A": "An instance is the set of integrity rules, while a schema is the actual data.",
      "B": "An instance represents the database’s current data, whereas a schema defines its structure.",
      "C": "An instance is stored in system catalogs, while a schema resides in user tables.",
      "D": "An instance is a view presented to a specific user, while a schema is the physical storage layout."
    },
    "correct_answer": "B",
    "explanation": "An instance is the collection of data rows that exist at a specific point in time; the schema is the blueprint that defines how those rows are organized.",
    "difficulty": "Medium"
  },
  {
    "question": "In the three‑schema architecture, which level provides a complete logical view of the database independent of any storage details?",
    "options": {
      "A": "External level",
      "B": "Conceptual level",
      "C": "Internal level",
      "D": "Physical level"
    },
    "correct_answer": "B",
    "explanation": "The conceptual level contains the entire logical schema and integrity constraints, abstracting away both user‑specific external views and physical storage specifics.",
    "difficulty": "Medium"
  },
  {
    "question": "Which form of data independence guarantees that adding or removing an index does **not** require changes to application programs?",
    "options": {
      "A": "Logical data independence",
      "B": "Physical data independence",
      "C": "Conceptual data independence",
      "D": "External data independence"
    },
    "correct_answer": "B",
    "explanation": "Physical data independence means that changes to the internal storage structures (e.g., indexes, file organization) are invisible to applications, so no program modifications are needed.",
    "difficulty": "Medium"
  },
  {
    "question": "Which statement about **metadata** in a DBMS is correct?",
    "options": {
      "A": "Metadata stores the actual business data entered by end users.",
      "B": "Metadata is kept in the catalog and describes objects such as tables, columns, and indexes.",
      "C": "Metadata is only used during database backup and recovery operations.",
      "D": "Metadata is synonymous with the database’s transaction log."
    },
    "correct_answer": "B",
    "explanation": "Metadata, stored in the system catalog, describes the structure of database objects (tables, columns, constraints, indexes) rather than the user data itself.",
    "difficulty": "Medium"
  }
]
